/**
 * Shared auth layer for a new Express host (docs/backend/auth.md). Runs right after the skeleton:
 *
 * - `src/generator-assets/express-mongoose/auth/**` → host, create-only (K). Module conditions in the files
 *   (`// @auth-file`, `// @if`) keep only the picked modules (`applyAuthBlocks`). Tokens as in the skeleton.
 * - `src/seed/initial-admin.ts`: first admin (bcrypt hash only).
 * - `package.json`: `jose` (Google / Apple), `nodemailer` (register / password reset).
 * - `.env.example`: the picked modules' keys.
 *
 * The `Users` model itself is a normal manifest model, generated by the caller (`bootstrapExpressProject`).
 */
import { existsSync, readFileSync, writeFileSync } from 'fs';
import { join, relative } from 'path';
import { AUTH_MAIL_ENV, AUTH_MODULE_INFO, authUsesMail, type AuthModule } from '../../../shared/authModules.js';
import { applyAuthBlocks } from '../../utils/authBlocks.js';
import type { AuthSeedAdmin } from '../../utils/authSeed.js';
import { getGeneratorAssetsDir } from '../../utils/templateHelpers.js';
import { WrittenFile, listFiles, writeOnce } from '../dotnet-efcore/dotnetFiles.js';
import { EXPRESS_APP_TOKEN, EXPRESS_PKG_TOKEN } from './ExpressHostBootstrap.js';

export const EXPRESS_AUTH_DEPENDENCIES = {
  jose: '6.2.15',
  nodemailer: '10.3.1'
} as const;
export const EXPRESS_AUTH_DEV_DEPENDENCIES = { '@types/nodemailer': '8.0.2' } as const;

function applyTokens(text: string, app: string, pkg: string): string {
  return text.split(EXPRESS_APP_TOKEN).join(app).split(EXPRESS_PKG_TOKEN).join(pkg);
}

export function expressAuthAssetsDir(): string {
  return join(getGeneratorAssetsDir('express-mongoose'), 'auth');
}

function initialAdminFile(admin: AuthSeedAdmin): string {
  return [
    '// İlk admin (docs/backend/auth.md "İlk admin"): Generator yazdı, yalnız bcrypt hash\'i tutar.',
    '// Açılışta hiç `admin` kullanıcı yoksa bu kayıt oluşturulur; sonra bu dosya bir daha okunmaz.',
    `export const initialAdmin = ${JSON.stringify(admin, null, 2)} as const;`,
    ''
  ].join('\n');
}

function sortKeys(record: Record<string, string>): Record<string, string> {
  return Object.fromEntries(Object.entries(record).sort(([a], [b]) => a.localeCompare(b)));
}

/** Adds the packages the picked modules import; existing versions are kept. */
function addPackages(root: string, modules: readonly AuthModule[]): void {
  const path = join(root, 'package.json');
  const pkg = JSON.parse(readFileSync(path, 'utf8')) as { dependencies?: Record<string, string>; devDependencies?: Record<string, string> };
  const deps = { ...pkg.dependencies };
  const dev = { ...pkg.devDependencies };
  if (modules.includes('google') || modules.includes('apple')) deps.jose ??= EXPRESS_AUTH_DEPENDENCIES.jose;
  if (authUsesMail(modules)) {
    deps.nodemailer ??= EXPRESS_AUTH_DEPENDENCIES.nodemailer;
    dev['@types/nodemailer'] ??= EXPRESS_AUTH_DEV_DEPENDENCIES['@types/nodemailer'];
  }
  pkg.dependencies = sortKeys(deps);
  pkg.devDependencies = sortKeys(dev);
  writeFileSync(path, `${JSON.stringify(pkg, null, 2)}\n`);
}

/** Appends the picked modules' env keys under one heading (once). */
function addEnvKeys(root: string, modules: readonly AuthModule[]): void {
  const path = join(root, '.env.example');
  if (!existsSync(path)) return;
  const text = readFileSync(path, 'utf8');
  const keys = [...modules.flatMap((m) => AUTH_MODULE_INFO[m].env), ...(authUsesMail(modules) ? AUTH_MAIL_ENV : [])].filter(
    (k) => !new RegExp(`^${k}=`, 'm').test(text)
  );
  if (!keys.length) return;
  const lines = ['', '# Auth modülleri (docs/backend/auth.md). SMTP_HOST boşsa e-postalar log\'a yazılır.', ...keys.map((k) => `${k}=`), ''];
  writeFileSync(path, `${text.replace(/\n*$/, '\n')}${lines.join('\n')}`);
}

export function bootstrapExpressAuth(
  root: string,
  app: string,
  pkg: string,
  modules: readonly AuthModule[],
  admin: AuthSeedAdmin
): { files: WrittenFile[] } {
  const dir = expressAuthAssetsDir();
  const files: WrittenFile[] = [];
  for (const file of listFiles(dir)) {
    const content = applyAuthBlocks(readFileSync(file, 'utf8'), modules);
    if (content === null) continue;
    files.push(writeOnce(join(root, applyTokens(relative(dir, file), app, pkg)), applyTokens(content, app, pkg)));
  }
  files.push(writeOnce(join(root, 'src/seed/initial-admin.ts'), initialAdminFile(admin)));
  addPackages(root, modules);
  addEnvKeys(root, modules);
  return { files };
}
